const SEGMENT = /^[A-Za-z0-9_]+$/;

function lookup(data, path) {
  if (path === '') throw new SyntaxError('a placeholder path is empty');
  const segments = path.split('.');
  for (const segment of segments) {
    if (!SEGMENT.test(segment)) throw new SyntaxError(`the path ${path} has a bad segment`);
  }

  let current = data;
  for (const segment of segments) {
    if (current === null || typeof current !== 'object') {
      throw new ReferenceError(`the path ${path} runs into a value that is not a container`);
    }
    if (!Object.prototype.hasOwnProperty.call(current, segment)) {
      throw new ReferenceError(`the path ${path} is missing`);
    }
    current = current[segment];
  }

  const kind = typeof current;
  if (kind !== 'string' && kind !== 'number' && kind !== 'boolean') {
    throw new TypeError(`the path ${path} is not a string, a number or a boolean`);
  }
  return String(current);
}

export function render(template, data) {
  if (typeof template !== 'string') throw new TypeError('template must be a string');
  if (data === null || typeof data !== 'object') throw new TypeError('data must be an object');

  let out = '';
  let i = 0;
  while (i < template.length) {
    if (template[i] === '\\' && template[i + 1] === '{' && template[i + 2] === '{') {
      out += '{{';
      i += 3;
      continue;
    }
    if (template[i] === '{' && template[i + 1] === '{') {
      const end = template.indexOf('}}', i + 2);
      if (end === -1) throw new SyntaxError('a placeholder was never closed');
      out += lookup(data, template.slice(i + 2, end).trim());
      i = end + 2;
      continue;
    }
    out += template[i];
    i += 1;
  }
  return out;
}
